#!/usr/bin/env python3
"""H7 Set A, job 4: file transform -- plain Python. Generated by
gen_jobs.py.
"""
from decimal import ROUND_HALF_UP, Decimal


def fmt(x):
    s = f"{x:.2f}"
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


with open("/tmp/planes_h7_bench/file_transform_input.csv", encoding="utf-8") as f:
    body = f.read()

rows = [line.split(",") for line in body.strip("\n").split("\n")]
out_lines = []
for id_, name, qty, price in rows:
    total = (Decimal(qty) * Decimal(price)).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP)
    out_lines.append(f"{id_},{name.upper()},{qty},{price},{fmt(total)}")

document = "\n".join(out_lines) + "\n"
with open("/tmp/planes_h7_bench/file_transform_output_py.csv", "w", encoding="utf-8") as f:
    f.write(document)

print(f"rows {len(rows)}")
